entries[444336] = { ["name"] = "Medaillon des Algariwettkämpfers", ["text"] = "Wirken in 2 sek. 2\nReagenzien:\nUnbändige Chiffre (2), Schattentinte (3), Sonnige Tinte (3), Wappenbuch des Wettkämpfers (#255) (3)\nOptionale Reagenzien:\nAuthentizität des Kunsthandwerks (#346) , Zeichenutensilien (#359)\nVerkäufer:\nHotharn\nZone:\nDornogal\nKosten:\n7500\nMuster:\nErhältlich im Auktionshaus\n\nMedaillon des Algariwettkämpfers\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)Schmuck\n+2.024 [Beweglichkeit oder Stärke oder Intelligenz] Benutzen: Entfernt alle bewegungseinschränkenden und Kontrollverlusteffekte.\n70\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators" }
entries[444337] = { ["name"] = "Inbrunstinsigne des Algariwettkämpfers", ["text"] = "Wirken in 2 sek. 2\nReagenzien:\nUnbändige Chiffre (2), Schattentinte (5), Sonnige Tinte (5), Wappenbuch des Wettkämpfers (#255) (5)\nOptionale Reagenzien:\nAuthentizität des Kunsthandwerks (#346) , Zeichenutensilien (#359)\nVerkäufer:\nHotharn\nZone:\nDornogal\nKosten:\n7500\nMuster:\nErhältlich im Auktionshaus\n\nInbrunstinsigne des Algariwettkämpfers\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\nErhöht Eure Tempowertung um + 1.040.\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren Primärwert für 20 Sek. um 4519 zu erhöhen.\n70\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators" }
