entries[444621] = { ["name"] = "Schutz der Errettung", ["text"] = "Erlernt folgenden Zauber.\n\nSchutz der Errettung\nStellt bei einem Verbündeten Gesundheit wieder her und gewährt ihm 8 Sek. lang 'Schutz der Errettung'.\n\nSolange 'Schutz der Errettung' anhält, gewährt die durch den Zaubernden erhaltene Heilung zusätzlich Absorption.\n\nWenn der Schutz abläuft, explodiert er und fügt allen Gegnern innerhalb von 40 Metern Heiligschaden in Höhe der verbleibenden Absorption zu, der gleichmäßig aufgeteilt wird." }
entries[444622] = { ["name"] = "Schutz der Errettung", ["text"] = "40 Meter Reichweite\nSofort 3 min Abklingzeit\nStellt bei einem Verbündeten Gesundheit wieder her und gewährt ihm 8 Sek. lang 'Schutz der Errettung'.\n\nSolange 'Schutz der Errettung' anhält, gewährt die durch den Zaubernden erhaltene Heilung zusätzlich Absorption.\n\nWenn der Schutz abläuft, explodiert er und fügt allen Gegnern innerhalb von 40 Metern Heiligschaden in Höhe der verbleibenden Absorption zu, der gleichmäßig aufgeteilt wird." }
entries[444623] = { ["name"] = "Symbiosis: Dummy Spell", ["text"] = "Wirken in 3.5 sek.\nTools: Schreibzeug des Virtuosen\nErlittener Schaden hat eine Chance, Euch und einem verbündeten Gruppenmitglied falls möglich Y lang einen gemeinsamen Absorptionsschild in Höhe von X zu gewähren. Wenn der Schild abläuft, erhalten beide Spielercharaktere Y Sek. lang X Vielseitigkeit." }
entries[444627] = { ["name"] = "Vivacity: Dummy Spell", ["text"] = "Wirken in 3.5 sek.\nTools: Schreibzeug des Virtuosen\nEure Zauber und Fähigkeiten haben eine Chance, Eurem Siegel ein Trommelfeuer der Lebhaftigkeit zu verleihen, das Euch hilft, wie es ihm beliebt.\n\nBei Auslösungen durch Schaden\n\nExplodiert im Kampf gegen mehrere Ziele nach 10 Sek. und verursacht X Feuerschaden.\n\nErhöht bei über 90% Gesundheit 15 Sek. lang den höchsten Sekundärwert um X.\n\nHeilt bei weniger als 30% Gesundheit um X Gesundheit.\n\nRichtet das Ziel hin, wenn es weniger als 20% Gesundheit hat und 'Hinrichten' möglich ist.\n\nWenn nichts davon zutrifft, wird der niedrigste Sekundärwert um Y erhöht.\n\nBei Auslösungen durch Heilung\n\nHeilt das Ziel um X Gesundheit, wenn es weniger als 50% Gesundheit hat.\n\nErhöht 15 Sek. lang den als höchsten Sekundärwert um X, wenn das Ziel mehr als 90% Gesundheit hat.\n\nGewährt X Mana, wenn Ihr weniger als 50% Mana habt.\n\nWenn nichts davon zutrifft, wird der niedrigste Sekundärwert um Y erhöht." }
