entries[444740] = { ["name"] = "Antimagische Hülle", ["text"] = "40 Meter Reichweite\nSofort\nUmgibt Euer Ziel 5 Sek. lang mit einer antimagischen Hülle, die bis zu [Gesamtgesundheit * 30 / 100 * (1 + Vielseitigkeit) * 1 * 1 ] Magieschaden absorbiert und schädliche magische Effekte abwehrt. Absorbierter Schaden erzeugt Runenmacht." }
entries[444741] = { ["name"] = "Antimagische Hülle", ["text"] = "40 Meter Reichweite\nSofort 1 min Abklingzeit\nUmgibt Euer Ziel 5 Sek. lang mit einer antimagischen Hülle, die bis zu [Gesamtgesundheit * 30 / 100 * (1 + Vielseitigkeit) * 1 * 1 ] Magieschaden absorbiert und schädliche magische Effekte abwehrt. Absorbierter Schaden erzeugt Runenmacht." }
entries[444743] = { ["name"] = "Feuerballsalve", ["text"] = "50 Meter Reichweite\nWirken in 3.5 sek.\nFügt allen Spielercharakteren innerhalb von 50 Metern 4121564 Feuerschaden zu." }
