entries[444754] = { ["name"] = "Schlüpfriges Schleudern", ["text"] = "Sofort\nEure Bewegungsgeschwindigkeit ist während 'Zeitverschiebung' um 40% erhöht." }
entries[444755] = { ["name"] = "Blubberndes Wachs", ["text"] = "Wirken in 3 sek.\nBenötigt Einhändig, Fernkämpfer, Fernkämpfer, Schildhand, Waffenhand, Zweihändig\nÜberzieht Eure Waffen mit einem blubbernden Wachs, das bis Abbruch lang anhält. Wenn Ihr giftige Effekte auf Euer Ziel anwendet, besteht die Chance, dass eine Lache aus kochendem Wachs von 4 Metern über dem Ziel ausgeschüttet wird, die 297 Feuerschaden verursacht, der auf die Gegner aufgeteilt wird.\n\nDer Schaden wird für jeden getroffenen Gegner erhöht, bis zu 5 Gegner." }
entries[444756] = { ["name"] = "Schaut nochmal", ["text"] = "'Versetzung' wird um 50% verlängert und hat eine 25% höhere Reichweite." }
entries[444763] = { ["name"] = "Apokalyptische Eroberung", ["text"] = "Unbegrenzte Reichweite\nSofort\nSolange Nazgrim aktiv ist, erhaltet Ihr 'Apokalyptische Eroberung', die Eure Stärke um 5% erhöht." }
entries[444764] = { ["name"] = "Gleve des Reißers", ["text"] = "Sofort\nDas Verbrauchen von [ Verwüstung : 6 /\n\nRachsucht\n20 ] Seelenfragmenten oder das Einsetzen von 'Die Jagd' verwandelt Euren nächsten Einsatz von 'Gleve werfen' in 'Gleve des Reißers'.\n\nGleve des Reißers :\nWirft eine mit der Essenz verschlungener Seelen verstärkte Gleve auf Euer Ziel. Diese verursacht (345% der Angriffskraft) körperlichen Schaden und prallt auf bis zu 2 weitere Gegner ab.\n\nBeginnt ein einstudiertes Muster der Glevenkunst, was Euren nächsten Einsatz von [ Verwüstung : 'Chaosstoß' / Fraktur : 'Fraktur' / 'Abscheren' ] und [ Verwüstung : 'Klingentanz' /\n\nRachsucht\n'Seelenspalter' ] verstärkt.\n\nDie verstärkte Fähigkeit, die Ihr als Erstes einsetzt, verursacht 10% mehr Schaden, die zweite 20% mehr Schaden." }
entries[444765] = { ["name"] = "Überprüfen" }
entries[444766] = { ["name"] = "Überprüfen" }
entries[444767] = { ["name"] = "Dominanz des Schlächters", ["text"] = "Ca. 7 Procs pro Minute\nEure Angriffe auf Euer Primärziel haben eine hohe Chance, dessen Abwehr zu überwältigen und 'Schlächterschlag' auszulösen. Verursacht (333.5% der Angriffskraft) Schaden und belegt Ziele mit 'Zum Tode verurteilt', wodurch der körperliche Schaden, den sie durch Euren nächsten Einsatz von 'Hinrichten' erleiden, um 15% erhöht wird. 3-mal stapelbar." }
entries[444769] = { ["name"] = "Bevorstehendes Ableben", ["text"] = "Ihr erhaltet bei jedem 3. Einsatz von 'Schlächterschlag' 'Plötzlicher Tod'.\n\nDer Einsatz von 'Plötzlicher Tod' beschleunigt Euren nächsten 'Klingensturm', wodurch er einmal öfter trifft (bis zu 3). Die Gesamtdauer von 'Klingensturm' bleibt unverändert." }
entries[444770] = { ["name"] = "Todestrieb", ["text"] = "Ihr heilt um 15% des durch 'Plötzlicher Tod' verursachten Schadens." }
entries[444771] = { ["name"] = "Kein Erbarmen zeigen", ["text"] = "'Zum Tode verurteilt' erhöht die kritische Trefferchance und den kritischen Trefferschaden Eures nächsten Einsatzes von 'Hinrichten' gegen das Ziel um 15%." }
entries[444772] = { ["name"] = "Überwältigende Klingen", ["text"] = "Jeder Treffer von 'Klingensturm' belegt alle betroffenen Gegner mit 'Überwältigt' und erhöht den Schaden, den Ihr ihnen zufügt, 20 Sek. lang um 1 %, maximal 10 Stapel." }
entries[444773] = { ["name"] = "Grausame Konsequenz", ["text"] = "Furor\nKritische Treffer mit 'Blutdurst' erhöhen den Schaden Eures nächsten Einsatzes von 'Blutdurst' um 20%.\n\nWaffen\nKritische Treffer mit 'Tödlicher Stoß' erhöhen den Schaden Eures nächsten Einsatzes von 'Tödlicher Stoß' um 20%." }
entries[444774] = { ["name"] = "Opportunist", ["text"] = "Furor\nWenn 'Wütender Schlag' seine eigene Abklingzeit abschließt, verursacht Euer nächster Einsatz von 'Wütender Schlag' 20% mehr Schaden und 20% mehr kritischen Schaden.\n\nWaffen\nWenn die Abklingzeit von 'Überwältigen' durch 'Taktiker' abgeschlossen wird, verursacht Euer nächster Einsatz von 'Überwältigen' 25% mehr Schaden sowie 25% mehr kritischen Schaden." }
entries[444775] = { ["name"] = "Sturm ernten", ["text"] = "Furor\n'Blutdurst' gewährt eine Chance von 20%, dass Ihr einen Wirbel aus Stahl entfesselt, der allen Gegnern in der Nähe (371.11% der Angriffskraft) körperlichen Schaden zufügt und sie mit 'Überwältigt' belegt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nWaffen\nWenn 'Tödlicher Stoß' und 'Spalten' mindestens 3 Ziele treffen, gewähren sie eine Chance von 20%, dass Ihr einen Wirbel aus Stahl entfesselt, der allen Gegnern in der Nähe (371.11% der Angriffskraft) körperlichen Schaden zufügt und sie mit 'Überwältigt' belegt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\n(Procchance: 20%, 500ms Abklingzeit)" }
entries[444776] = { ["name"] = "Unerbittliche Verfolgung", ["text"] = "'Sturmangriff' erhöht Eure Bewegungsgeschwindigkeit 3 Sek. lang um 70%.\n\n'Sturmangriff' entfernt alle bewegungseinschränkenden Effekte. Dieser Effekt kann nur einmal alle 30 Sek. auftreten." }
entries[444777] = { ["name"] = "Boshafte Beweglichkeit", ["text"] = "'Heldenhafter Sprung' verringert die Abklingzeit von 'Sturmangriff' um 5 Sek. und 'Sturmangriff' verringert die Abklingzeit von 'Heldenhafter Sprung' um 2 Sek." }
entries[444778] = { ["name"] = "Ausmerzender Zyklon", ["text"] = "Jeder Treffer von 'Klingensturm' verursacht 10% zusätzlichen Schaden, der gleichmäßig auf alle Ziele aufgeteilt wird." }
entries[444779] = { ["name"] = "Bösartigkeit des Schlächters", ["text"] = "Furor\nSchaden von 'Wütender Schlag' um 30% erhöht.\n\nWaffen\nSchaden von 'Überwältigen' um 30% erhöht." }
entries[444780] = { ["name"] = "Unerbittlicher Ansturm", ["text"] = "Wenn Ihr ein Ziel mit 'Hinrichten' angreift, das Ihr 'Zum Tode verurteilt' habt, wird die Abklingzeit von 'Klingensturm' um 5 Sek. verringert und Ihr belegt das Ziel für jeden verbrauchten Stapel von 'Zum Tode verurteilt' mit 2 Stapeln von 'Überwältigt'.\n\nIhr könnt 'Zuschlagen' und 'Sturmblitz' einsetzen, während 'Klingensturm' aktiv ist." }
entries[444784] = { ["name"] = "Geisterhaftes Bild", ["text"] = "Euer 'Spiegelbild' beschwört einen zusätzlichen Klon.\n'Spiegelbild' verringert nun allen erlittenen Schaden zusätzlich um 5%." }
entries[444785] = { ["name"] = "Blutbarsch", ["text"] = "Sofort\nEin kleiner Fisch mit blutroten Schuppen, der in Gewässern in ganz Khaz Algar vorkommt. Wenn er sich bedroht fühlt, stoßen seine Kiemen eine zähflüssige Tinte aus, die Blut sehr ähnlich sieht.\n\nBesondere Verwendung:\n\nBlutiger Köder\n\nWenn Ihr diesen Fisch zurück in die Gewässer von Khaz Algar werft, kann dieser Mechanismus aktiviert werden. Dabei werdet Ihr mit Pheromonen bedeckt, die beim Fangen des scheuen blutroten Dornhais helfen.\n\nVerbreitungsgebiete:\n\n- Insel von Dorn\n- Schallende Tiefen\n- Heilsturz\n- Sireneninsel\n- K'aresh-Oase\n\nFischschwärme:\n\n- Slumhaischwarm\n- Blut im Wasser\n- Schwärender Fäulnisteich\n- Blutbarschschwarm\n- Ruhige Oberflächenwellen\nBeruf:\nAngeln" }
entries[444786] = { ["name"] = "Kristalliner Stör", ["text"] = "5 Meter Reichweite\nSofort\nMit seinem schlanken, länglichen Körper gleitet der Fisch mühelos durch die Gewässer von Khaz Algar. Im Vergleich zu seiner verwandten Art, dem Bismutbitterling, ist dieser urzeitliche Fisch deutlich größer. Er folgt aber gern Schwärmen seines kleineren Cousins, um die Nährstoffe aufzunehmen, die die Fische verlieren.\n\nBesondere Verwendung:\n\nWahrnehmung\n\nWerft diesen Fisch zurück ins Wasser, um Eure Wahrnehmung von Khaz Algar zu erhöhen.\n\nVerbreitungsgebiete:\n\n- Insel von Dorn\n- Schallende Tiefen\n- Sireneninsel\n\nFischschwärme:\n\n- Glimmerbecken\nBeruf:\nAngeln" }
entries[444787] = { ["name"] = "Bismutbitterling", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDer kleine Fisch mit seinem fratzenhaften Ausdruck hat harte äußere Schuppen, die an Bismut erinnern. Diese Schuppen nehmen Mineralien und andere Schwebeteilchen auf und transportieren sie durch die Gewässer von Khaz Algar. Ein gewöhnlicher Fisch, der jedoch sehr wichtig für das Gedeihen der örtlichen Flora ist.\n\nBesondere Verwendung:\n\nKöder\n\nWerft diesen Fisch zurück ins Wasser, um Eure Angelfertigkeit zu erhöhen.\n\nVerbreitungsgebiete:\n\n- Insel von Dorn\n- Schallende Tiefen\n- Sireneninsel\n\nFischschwärme:\n\n- Glimmerbecken\nBeruf:\nAngeln" }
entries[444788] = { ["name"] = "Knabberelritze", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nEine unscheinbare Elritze, die unerfahrene Angler womöglich als wertlos erachten. Gerüchteweise versammelt sich der Fisch aber um besonders glänzende Gegenstände und knabbert am Schmutz, den sie ansetzen.\n\nBesondere Verwendung:\n\nWahrnehmung\n\nWerft diesen Fisch zurück ins Wasser, um Eure Wahrnehmung von Khaz Algar zu erhöhen.\n\nVerbreitungsgebiete:\n\n- Insel von Dorn\n- Schallende Tiefen\n- Heilsturz\n- Azj-Kahet\n- Sireneninsel\n-Lorenhall\n- K'aresh-Oase\n\nFischschwärme:\n\n- Ruhige Oberflächenwellen\nBeruf:\nAngeln" }
entries[444789] = { ["name"] = "Flüsternder Sterngucker", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDer Fisch tritt in dichten Schwärmen auf und hat seinen Namen durch seine tintenschwarzen Schuppen erhalten, die aneinander reiben und vibrieren. Diese Vibrationen schrecken Räuber ab und sind so laut, dass man sie selbst über Wasser hören kann.\n\nBesondere Verwendung:\n\nGeflüster der Tiefe\n\nSetzt den flüsternden Sterngucker ein, um schlummernde Quastenflosser aus den Tiefen Azj-Kahets hervorzulocken.\n\nVerbreitungsgebiete:\n\n- Insel von Dorn\n- Schallende Tiefen\n- Heilsturz\n- Sireneninsel\n- K'aresh-Oase\n\nFischschwärme:\n\n- Sternguckerschwarm\nBeruf:\nAngeln" }
entries[444790] = { ["name"] = "Goldkiemenforelle", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDie Risse in seinen Kiemen schimmern leuchtend golden. Angler erzählen sich, dass der Fisch Glück, Wohlstand und ruhige See bringt.\n\nBesondere Verwendung:\n\nWahrnehmung\n\nDiesen Fisch zu fangen, erhöht Eure Wahrnehmung von Khaz Algar.\n\nVerbreitungsgebiete:\n\n- Insel von Dorn\n- Schallende Tiefen\n- Heilsturz\n- Azj-Kahet\n- Sireneninsel\n- Lorenhall\n- K'aresh-Oase\n\nFischschwärme:\n\n- Glimmerbecken\n- Schwärender Fäulnisteich\n- Energieerfüllter Sekretfleck\nBeruf:\nAngeln" }
entries[444791] = { ["name"] = "Spiegelregenbogenfisch", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDas mehrfarbige Blut, das unter seinen durchscheinenden Schuppen fließt, verleiht diesem Fisch sein regenbogenartiges Aussehen. Neben dem kulinarischen Wert das Fleischs von Regenbogenfischen ist deren Blut auch fast identisch mit dem Perlmuttpigment, das Schreiber verwenden.\n\nBesondere Verwendung:\n\nFrisches Filet\n\nDie Verwertung dieses Fisches mit der Kochfertigkeit kann frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n- Insel von Dorn\n- Schallende Tiefen\n- Sireneninsel\n- K'aresh-Oase\n\nFischschwärme:\n\n- Glimmerbecken\nBeruf:\nAngeln" }
entries[444792] = { ["name"] = "Trödelnder Häsling", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nEin frecher Fisch, der durch Khaz Algar saust. Er wird oft mit einer Knabberelritze oder einem majestätischen Zwergbarsch verwechselt und findet sich dank seiner Geschwindigkeit und Größe oft an Orten wieder, an denen er nichts verloren hat.\n\nBesondere Verwendung:\n\nKöder\n\nWerft den Fisch zurück ins Wasser, um Eure Angelfertigkeit zu erhöhen.\n\nVerbreitungsgebiete:\n\n- Insel von Dorn\n- Schallende Tiefen\n- Heilsturz\n- Sireneninsel\n- K'aresh-Oase\n\nFischschwärme:\n\n- Ruhige Oberflächenwellen\n- Blut im Wasser\n- Schwärender Fäulnisteich\nBeruf:\nAngeln" }
entries[444793] = { ["name"] = "Dornischer Hecht", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nEine unscheinbare Kreatur, die sich mit ihrem gepunkteten Aussehen tarnt, um Angriffe von oben zu vermeiden, während sie auf kleinere Fische unten lauert. Mit dem großen, fleischigen Körper macht sie Jagd auf kristalline Störe, ist aber auch eine hervorragende Quelle für frisches Filet.\n\nBesondere Verwendung:\n\nFrisches Filet\n\nDie Verwertung dieses Fisches mit der Kochfertigkeit kann frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n- Insel von Dorn\n- Schallende Tiefen\n- Heilsturz\n- Sireneninsel\n\nFischschwärme:\n\n- Ruhige Oberflächenwellen\nBeruf:\nAngeln" }
entries[444794] = { ["name"] = "Tosender Anglersucher", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nEin aggressiver Fisch, der sich gern dort versammelt, wo Angler sind. Wenn er mit seiner kraftvollen Schwanzflosse und seinem muskulösen Leib durch die Wellen stößt, erzeugt er ein hörbares Rauschen.\n\nBesondere Verwendung:\n\nFrisches Filet\n\nDie Verwertung dieses Fisches mit der Kochfertigkeit kann frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n- Insel von Dorn\n- Schallende Tiefen\n- Heilsturz\n- Azj-Kahet\n- Sireneninsel\n\nFischschwärme:\n\n- Anglersucherstrom\nBeruf:\nAngeln" }
entries[444795] = { ["name"] = "Arathorhammerfisch", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDie Krone am Kopf dient als ernstzunehmende Waffe, wenn er mit seinen riesigen Flossen nach vorn stößt. Mit Schuppen, die fast im Farbton der Arathi schimmern, ist es kein Wunder, dass der muskulöse Fisch diesen Namen trägt.\n\nBesondere Verwendung:\n\nHolzhammermethode\n\nSchlägt Euren Gegner mit dem Hammerfisch und betäubt ihn für 1 Sek. Nur im Freien in Khaz Algar einsetzbar.\n\nVerbreitungsgebiete:\n\n- Heilsturz\n\nFischschwärme:\n\n- Blut im Wasser\nBeruf:\nAngeln" }
entries[444796] = { ["name"] = "Majestätischer Zwergbarsch", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDunkelrote und magentafarbene Streifen zieren den kleinen, aber kraftvollen Leib. Dieser besonders seltene Fisch am königlichen Hof schützt die Gewässer um Königinnenköderfische aggressiv vor Arten wie dem verderbten Geisterfisch.\n\nBesondere Verwendung:\n\nKönigsköder\n\nWehrt verderbte Geisterfische ab und sorgt für sichere Gewässer für Königinnenköderfische.\n\nVerbreitungsgebiete:\n\n- Heilsturz\n- Azj-Kahet\n\nFischschwärme:\n\n- Königliche Welle\nBeruf:\nAngeln" }
entries[444797] = { ["name"] = "Slumhai der Kaheti", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nIn den Tiefen Azj-Kahets gleitet diese Kreatur über den Boden, ihre Silhouette kaum von den finsteren Tiefen zu unterscheiden. Dieses berechnende Raubtier lässt selbst erfahrene Angler von Glück reden.\n\nBesondere Verwendung:\n\nFrisches Filet\n\nDie Verwertung dieses Fisches mit der Kochfertigkeit kann eine große Menge frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n- Heilsturz\n- Azj-Kahet\n\nFischschwärme:\n\n- Blut im Wasser\n- Schwarm Slumhaie\nBeruf:\nAngeln" }
entries[444798] = { ["name"] = "Blasser Hüllenfisch", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDieser große Fisch wird oft mit einem verderbten Geisterfisch verwechselt, ist aber der beste Freund jedes Anglers. Angezogen von Mineralien am Grund von Gewässern neigt der blasse Hüllenfisch dazu, eingebettete Kleintiere zu verschlingen.\n\nBesondere Verwendung:\n\nHüllenfischmagen\n\nWeidet den Fisch aus in Hoffnung auf Schätze.\n\nVerbreitungsgebiete:\n\n- Azj-Kahet\n-Lorenhall\n\nFischschwärme:\n\n- Energieerfüllter Sekretfleck\n- Schwärender Fäulnisteich\nBeruf:\nAngeln" }
entries[444799] = { ["name"] = "Blutroter Dornhai", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDer blutrote Dornhai ist ein Meister des Hinterhalts und verfolgt kleinere Fische geduldig, bevor er seine karmesinroten Flossen für einen Geschwindigkeitsschub in Position bringt. Dieser große, scheue Fisch wird vor allem von Blutbarschschwärmen angezogen.\n\nBesondere Verwendung:\n\nFrisches Filet\n\nDie Verwertung dieses Fisches mit der Kochfertigkeit kann eine große Menge frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n- Insel von Dorn\n- Schallende Tiefen\n- Heilsturz\n- Azj-Kahet\n- Sireneninsel\n- K'aresh-Oase\n\nFischschwärme:\n\n- Blutbarschschwarm\n- Blut im Wasser\nBeruf:\nAngeln" }
entries[444800] = { ["name"] = "Stacheliger Seerabe", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nSein Körper ist mit scharfen Spitzen übersät, die in alle Richtungen zeigen und ihn in eine furchterregende Rüstung kleiden. Diese Spitzen dienen sowohl dem Schutz als auch der Tarnung auf dem steinigen Meeresboden, auf dem er sich oft aufhält. Trotz seines formidablen Äußeren bewegt er sich überraschend anmutig und schwimmt mühelos durch Unterwasserspalten und -höhlen.\n\nBesondere Verwendung:\n\nFrisches Filet\n\nDie Verwertung dieses Fisches mit der Kochfertigkeit kann eine große Menge frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n- Insel von Dorn\n- Heilsturz\n- Sireneninsel\n\nFischschwärme:\n\n- Ruhige Oberflächenwellen\n- Glimmerbecken\n- Sternguckerschwarm\n- Anglersucherstrom\nBeruf:\nAngeln" }
entries[444801] = { ["name"] = "Königinnenköderfisch", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nSein langgezogener Körper ist mit farbenfroh schimmernden, schillernden Schuppen geschmückt. Eine biolumineszente Angel hängt von seiner Stirn wie ein glühender Edelstein. Dieser Fisch gleitet anmutig durch die tintenschwarzen Tiefen von Khaz Algar und gedeiht dank seiner scharfen Sinne in der Dunkelheit.\n\nBesondere Verwendung:\n\nFrisches Filet\n\nDie Verwertung dieses Fisches mit der Kochfertigkeit kann eine große Menge frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n- Heilsturz\n- Azj-Kahet\n\nFischschwärme:\n\n- Königliche Welle\nBeruf:\nAngeln" }
entries[444802] = { ["name"] = "Verfluchter Geisterfisch", ["text"] = "5 Meter Reichweite\nSofort\nVom Blut der Alten Götter verzerrt, spannt sich seine kränkliche, blasse Haut über seinen skelettartigen Körper. Angler in ganz Khaz Algar bezeichnen diesen Fisch als einen Boten der Verdammnis, der jeden Angler verflucht, der das Pech hat, ihn an Land zu ziehen. Wenn man dieser Kreatur in die Augen schaut, wird ihre Verdorbenheit nur noch umfassender, denn jedes Spiegelbild wird vom Abgrund verschlungen.\n\nDas Fangen dieses Fisches bewirkt:\n\nGeisterfischfluch\n\nAber noch besteht Hoffnung. Angler mögen den verfluchten Geisterfisch meiden, doch für Köche ist er eine Gelegenheit. Die Verwertung dieses Fisches könnte Eurem Magen und Eurer Angelfertigkeit zum Vorteil gereichen.\n\nVerbreitungsgebiete:\n\n- Überall da, wo ein übermütiger Algarischer Angler seine Angel auswerfen kann.\n\nFischschwärme:\n\n- Alle Schwärme.\nBeruf:\nAngeln" }
entries[444803] = { ["name"] = "Erwachter Quastenflosser", ["text"] = "5 Meter Reichweite\nSofort\nEine einfache, schlummernde Kreatur. Wenn sie erwacht, schimmern ihre Schuppen in allen Farben des Regenbogens und reflektieren jeden noch so kleinen Lichtstrahl. Eine ruhige Erhabenheit und ein treffliches Ziel für jeden aufstrebenden Angler.\n\nBesondere Verwendung:\n\nFrisches Filet\n\nDie Verwertung dieses Fisches mit der Kochfertigkeit kann eine große Menge frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n- Azj-Kahet\n- K'aresh-Oase\nBeruf:\nAngeln" }
entries[444806] = { ["name"] = "Wut der Aldrachi", ["text"] = "Sofort\nDas Verbrauchen von [ Verwüstung : 6 /\n\nRachsucht\n20 ] Seelenfragmenten oder das Einsetzen von 'Die Jagd' verwandelt Euren nächsten Einsatz von 'Gleve werfen' in 'Gleve des Reißers'.\n\nGleve des Reißers :\nWirft eine mit der Essenz verschlungener Seelen verstärkte Gleve auf Euer Ziel. Diese verursacht (345% der Angriffskraft) körperlichen Schaden und prallt auf bis zu 2 weitere Gegner ab.\n\nBeginnt ein einstudiertes Muster der Glevenkunst, was Euren nächsten Einsatz von [ Verwüstung : 'Chaosstoß' / Fraktur : 'Fraktur' / 'Abscheren' ] und [ Verwüstung : 'Klingentanz' /\n\nRachsucht\n'Seelenspalter' ] verstärkt.\n\nDie verstärkte Fähigkeit, die Ihr als Erstes einsetzt, verursacht 10% mehr Schaden, die zweite 20% mehr Schaden." }
entries[444808] = { ["name"] = "Hilferuf" }
entries[444810] = { ["name"] = "Kunst der Gleve", ["text"] = "8 Meter Reichweite\nSofort\nVerwüstung\nNach dem Verbrauch eines Seelenfragments verursacht Euer nächster Einsatz von 'Chaosstoß' (40% der Angriffskraft) zusätzlichen körperlichen Schaden.\n\n'Teufelsklinge' verbraucht bis zu 5 Seelenfragmente in der Nähe.\n\nRachsucht\nNach dem Verbrauch eines Seelenfragments verursacht Euer nächster Einsatz von (40% der Angriffskraft) zusätzlichen körperlichen Schaden." }
