entries[444827] = { ["name"] = "Reaktive Barriere", ["text"] = "Frost\nEure 'Eisbarriere' kann je nach Eurer fehlenden Gesundheit bis 50% mehr Schaden absorbieren.\n\nMax. Effektivität, wenn die Gesundheit weniger als 50% beträgt.\n\nArkan\nEure 'Prismatische Barriere' kann je nach Eurer fehlenden Gesundheit bis 50% mehr Schaden absorbieren.\n\nMax. Effektivität, wenn die Gesundheit weniger als 50% beträgt." }
