entries[444995] = { ["name"] = "Wogendes Totem", ["text"] = "6.5% von Grundmana 40 Meter Reichweite\nSofort 30 sek. Abklingzeit\nWiederherstellung\nBeschwört ein Totem am Zielort, das 24 Sek. lang 'Heilender Regen' mit 30% höherer Effektivität aufrechterhält.\n\nErsetzt 'Heilender Regen'.\n\nVerstärkung\nBeschwört ein Totem am Zielort, das sofort und danach alle 6 Sek. ein 'Beben' auslöst und (58.2769% der Angriffskraft) Flammenschlagschaden verursacht. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. Hält 24 Sek. lang an." }
