entries[445017] = { ["name"] = "Gieriger Hunger", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchleudert einen kyrianischen Speer an den Zielort, der sofort (110% der Angriffskraft) Arkanschaden und im Verlauf von 4 Sek. zusätzlich (120% der Angriffskraft) Schaden verursacht. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n\nGetroffene Gegner werden für die Dauer an die Position des Speers der Bastion gebunden.\n\nErzeugt 25 Wut." }
entries[445018] = { ["name"] = "Unvergessener Totschläger", ["text"] = "100 Meter Reichweite\nSofort\nWeckt einen schlafenden Peon auf." }
entries[445019] = { ["name"] = "Unersättlicher Verzehr", ["text"] = "Sofort\nDer verlorene Wächter verzehrt sämtliche ' Septische Galle ', der er begegnet. Entfernt die Galle und erhöht seinen verursachten Schaden um 5%. Dieser Effekt ist stapelbar." }
