entries[445021] = { ["name"] = "Nulldetonation", ["text"] = "Wirken in 4 sek.\nDer beschworene Akolyth fügt allen Spielercharakteren 690758 Schattenschaden zu. Jeder erfolgreiche Einsatz erhöht diesen verursachten Schaden um 100%." }
entries[445024] = { ["name"] = "Wirbelnde Elemente", ["text"] = "Verstärkung\nElementare Partikel schweben um Euer Wogendes Totem herum. Eure Fähigkeiten verbrauchen die Partikel für verstärkte Effekte.\n\nLuft: [ Verstärkung : Euer nächster Einsatz von 'Blitzschlag', 'Kettenblitzschlag' oder 'Elementarschlag' entfesselt 3 'Wogende Blitze' auf Euer 'Wogendes Totem' /\n\nElementar, Wiederherstellung\nDie Zauberzeit Eures nächsten Heilzaubers ist um 40% verringert ]\nErde: [ Verstärkung : Euer nächster 'Flammenschock' verursacht 300% mehr direkten Schaden und trifft 5 Gegner in der Nähe /\n\nElementar, Wiederherstellung\nEure nächste 'Kettenheilung' gewährt allen getroffenen Zielen 'Lebensgeister' mit 150% Effektivität ]\nFeuer: Eure nächste 'Lavapeitsche' oder 'Feuernova' gewährt Euch 6 Sek. lang 'Heiße Hand'.\n\nWiederherstellung\nElementare Partikel schweben um Euer Wogendes Totem herum. Eure Fähigkeiten verbrauchen die Partikel für verstärkte Effekte.\n\nWasser: Euer nächster Einsatz von 'Welle der Heilung' oder 'Heilende Woge' heilt zusätzlich einen Verbündeten im Effektbereich Eures Zaubers 'Heilender Regen' mit einer Effektivität von 100%.\n\nLuft: [ Verstärkung : Euer nächster Einsatz von 'Blitzschlag', 'Kettenblitzschlag' oder 'Elementarschlag' entfesselt 3 'Wogende Blitze' auf Euer 'Wogendes Totem' /\n\nElementar, Wiederherstellung\nDie Zauberzeit Eures nächsten Heilzaubers ist um 40% verringert ]\nErde: [ Verstärkung : Euer nächster 'Flammenschock' verursacht 300% mehr direkten Schaden und trifft 5 Gegner in der Nähe /\n\nElementar, Wiederherstellung\nEure nächste 'Kettenheilung' gewährt allen getroffenen Zielen 'Lebensgeister' mit 150% Effektivität ]" }
entries[445025] = { ["name"] = "Totemischer Abpraller", ["text"] = "Ca. 10 Procs pro Minute\nVerstärkung\n'Blitzschlag', 'Kettenblitzschlag' und 'Elementarschlag' haben eine Chance, 'Wogender Blitz' auf Euer Wogendes Totem zu werfen, was den Schaden des Totems um 10% erhöht und den Blitz dann auf Euer Ziel weiterleitet, wo er (92% der Angriffskraft) Naturschaden verursacht. Der Schadensbonuseffekt ist stapelbar.\n\nWiederherstellung\n'Kettenheilung' springt jetzt auf ein Totem innerhalb von 20 Metern über, sobald das letzte Ziel erreicht wurde, wodurch das Totem 'Kettenheilung' auf einen verletzten Verbündeten innerhalb von 30 Metern wirkt und diesen um (150% der Zaubermacht) Gesundheit heilt. Springt auf bis zu 2 Ziele innerhalb von 20 Metern über." }
entries[445026] = { ["name"] = "Übergroße Totems", ["text"] = "Erhöht die Größe und den Radius Eurer Totems um 15% und deren Heilung um 30%." }
entries[445027] = { ["name"] = "Rascher Rückruf", ["text"] = "Das erfolgreiche Entfernen eines schädlichen Effekts durch Euer Totem des Erdstoßes oder Totem der Giftreinigung oder das Kontrollieren eines Gegners durch Euer Totem der Energiespeicherung oder Totem des Erdgriffs verringert die Abklingzeit des verwendeten Totems um 5 Sek.\n\nKann pro Totem nicht öfter als einmal alle 20 Sek. auftreten." }
entries[445028] = { ["name"] = "Verzauberungsmeisterschaft", ["text"] = "Verstärkung\nErhöht die Chance, dass die 'Windzornwaffe' ausgelöst wird, um 5%, und erhöht ihren Schaden um 8%.\n\nWenn Angriffe mit der 'Windzornwaffe' die 'Waffe der Flammenzunge' auslösen, hat sie eine Chance, einen Flammenwirbel um das Ziel herum zu beschwören, der allen Gegnern in der Nähe 300% ihres Schadens zufügt.\n\nWiederherstellung\nErhöht die Dauer Eures Effekts 'Lebensgeister' um 3 Sek." }
entries[445029] = { ["name"] = "Verstärkungskern", ["text"] = "Während Euer Wogendes Totem aktiv ist, sind Euer verursachter Schaden und Heilung um 3% erhöht." }
entries[445030] = { ["name"] = "Überwoge", ["text"] = "Wiederherstellung\nWährend 'Aszendenz' verursacht Euer Wogendes Totem 50% mehr Schaden .\n\nVerstärkung\nWährend 'Aszendenz' verursacht Euer Wogendes Totem 50% mehr Schaden." }
entries[445031] = { ["name"] = "Windbarriere", ["text"] = "Wenn Ihr ein aktives Totem habt, gewähren Eure Totems Euch 30 Sek. lang alle 30 Sek. einen Schild, der (Gesamtgesundheit * 6 / 100) Schaden absorbiert." }
entries[445032] = { ["name"] = "Impulskondensator", ["text"] = "Verstärkung\nErhöht den Schaden von des Wogenden Totems um 18%.\n\nWiederherstellung\nErhöht die durch Wogendes Totem verursachte Heilung um 25%." }
entries[445033] = { ["name"] = "Unterstützende Verzauberungen", ["text"] = "Verstärkung\nErhöht die kritische Trefferchance von 'Waffe der Flammenzunge' um 25% und den kritischen Trefferschaden um 100%.\n\nWiederherstellung\nLernt eine neue Waffenverzauberung: 'Wache des Gezeitenrufers'.\n\nWache des Gezeitenrufers\nErfüllt Euren Schild 1 Stunde lang mit dem Element des Wassers. Erhöht Eure hervorgerufene Heilung um 2.0% und die Dauer Eures Totems des heilenden Flusses und Totems des Wolkenbruchs um 3.0 Sek." }
entries[445034] = { ["name"] = "Lebhafte Totems", ["text"] = "Verstärkung\n'Lavapeitsche' hat eine Chance, ein Totem der Verbrennung zu beschwören, das 'Sengende Blitze' schleudert, die Gegnern in der Nähe (65.205% der Zaubermacht) Feuerschaden zufügen. Hält 8 Sek. lang an.\n\n'Frostschocks', die durch 'Hagelsturm', 'Lavapeitsche' oder 'Feuernova' ermächtigt wurden, lassen Eure 'Totems der Verbrennung' eine 'Verbrennende Salve' auf bis zu 5 Gegner in der Nähe schleudern, die (92.736% der Zaubermacht) Feuerschaden verursacht.\n\nWiederherstellung\nWenn Ihr ein 'Totem der Heilungsflut', 'Totem des heilenden Flusses', 'Totem des Wolkenbruchs', oder 'Totem der Geistverbindung' beschwört, zaubert Ihr einen kostenlosen Spontanzauber von 'Kettenheilung' mit 100% Effektivität." }
entries[445035] = { ["name"] = "Reaktivität", ["text"] = "Wiederherstellung\nEure 'Totems des heilenden Flusses' heilen jetzt auch einen zweiten Verbündeten mit 100% Effektivität.\n\n'Totem des Wolkenbruchs' speichert 25% zusätzliche Heilung.\n\nVerstärkung\nWährend 'Heiße Hand' aktiv ist, lässt 'Lavapeitsche' die Erde aufreißen und verursacht eine 'Zerschlagung' mit 50% Effektivität.\n\nDie 'Zerschlagung' aus diesem Effekt verursacht keine Handlungsunfähigkeit." }
entries[445036] = { ["name"] = "Totemische Koordination", ["text"] = "Wiederherstellung\n'Kettenheilung' von 'Lebendiges Totem' und 'Totemischer Abpraller' ist 25% effektiver.\n\nVerstärkung\nErhöht die kritische Trefferchance der Angriffe Eures Totems der Verbrennung um 15% und den kritischen Trefferschaden um 30%." }
