entries[445066] = { ["name"] = "Ovi'nax' quecksilbriges Ei", ["text"] = "Balanciert sorgfältig die Bebrütung des Eis aus. Bei Stillstand erhaltet Ihr alle 1 Sek. 2 Hauptwert, bis zu 30-mal. Schwindet bei Bewegung. Bei Bewegung erhaltet Ihr alle 1 Sek. 6 Eures höchsten Sekundärwerts, bis zu 30-mal. Schwindet bei Stillstand.\n\nWeitere Stapel nach dem 20. Stapel gewähren 60% verringerte Vorteile." }
