entries[445082] = { ["name"] = "Filet am Spieß", ["text"] = "Wirken in 2 sek.\nReagenzien:\nFrisches Filet (5)\nOptionale Reagenzien:\nGeheimzutat (#318)\nRezept für 3 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nBerufsausbilder:\nKochkunst von Khaz Algar (1)\nKosten:\n60\n\nFilet am Spieß\nBenutzen: Stellt im Verlauf von 20 Sek. ( 375000 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nSatt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Satt ' und Euer niedrigster Sekundärwert wird 15 Min. lang um [Quellwert] erhöht.\n68", ["unresolvedValues"] = true }
