entries[445090] = { ["name"] = "Fleisch und Kartoffeln", ["text"] = "Wirken in 2 sek. 2\nReagenzien:\nPortioniertes Steak (8), Gezwirnte Kräuter (8), Kernwegstaub (5)\nOptionale Reagenzien:\nGeheimzutat (#318)\nRezept für 3 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nBerufsausbilder:\nKochkunst von Khaz Algar (35)\nKosten:\n200\n\nFleisch und Kartoffeln\nBenutzen: Stellt im Verlauf von 20 Sek. ( 1350000 / 5 * 20) Gesundheit und ( 675000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nSatt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Satt ' und erhaltet 1 Stunde lang [Quellwert] Ausdauer und [Quellwert] Stärke.\n68", ["unresolvedValues"] = true }
