entries[445117] = { ["name"] = "Gehackte Mykopracht", ["text"] = "Wirken in 1 sek.\nZerkleinert 5 Mykopracht zu einer Zutat, die für verschiedene Gerichte von Khaz Algar verwendet wird. Das Kraut wird dabei verbraucht. Wie viel gehackte Mykopracht Ihr erhaltet, hängt von Eurer Kochfertigkeit und der Reagenzqualität ab.\nBeruf:\nKochkunst (1)" }
entries[445118] = { ["name"] = "Portioniertes Steak", ["text"] = "Wirken in 1 sek.\nPortioniert 5 Fleischstücke, um eine Zutat zu schaffen, die in verschiedenen Speisen aus Khaz Algar verwendet wird. Das Fleisch wird dabei verbraucht. Wie viele portionierte Steaks Ihr erhaltet, hängt von Eurer Kochfertigkeit ab.\nBeruf:\nKochkunst (1)" }
entries[445119] = { ["name"] = "Gewürzter Fleischfond", ["text"] = "Wirken in 1 sek.\nWürzt 5 Fleischstücke, um eine Zutat zu schaffen, die in verschiedenen Speisen aus Khaz Algar verwendet wird. Das Fleisch wird dabei verbraucht. Wie viel gewürzten Fleischfond Ihr erhaltet, hängt von Eurer Kochfertigkeit ab.\nBeruf:\nKochkunst (1)" }
entries[445120] = { ["name"] = "Herzhaftes Essen", ["text"] = "Wirken in 1 sek. 2\nKombiniert 5 Eurer Lieblingsmahlzeiten, um eine Version zu schaffen, die Euch gewiss sättigt.\n\nHerzhaftes Essen bleibt über den Tod hinaus erhalten und kann in Eurer Kriegsmeute geteilt werden.\nBeruf:\nKochkunst (25)" }
entries[445122] = { ["name"] = "Geschmolzene Lanze", ["text"] = "25 Meter Reichweite\nKanalisiert (Wirken in 3 sek.)\nNutzt immense Hitze, um Felsbrocken präzise und mühelos zu beseitigen." }
entries[445123] = { ["name"] = "Bulliger Zusammenstoß", ["text"] = "Unbegrenzte Reichweite\nWirken in 5 sek.\nUlgrax springt in die Mitte der Arena und zerschmettert den Boden. Dabei fügt er allen Spielercharakteren 5756315 körperlichen Schaden zu und stößt sie zurück. Spielercharaktere, die weiter vom Ziel entfernt sind, erleiden weniger Schaden." }
