entries[445323] = { ["name"] = "Runenverzierte Nullsteinrute", ["text"] = "Wirken in 3.5 sek. 2\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nHändchen fürs Kunsthandwerk (400), Barren der Schallenden Tiefen (2), Nullstein , Sturmstaub (100), Schimmernder Splitter (10)\nOptionale Reagenzien:\nHerstellungswerte anpassen (#345) , Verzauberungen und Ausrüstung (#378) , Authentizität des Kunsthandwerks (#354)\nVerkäufer:\nLyrendal\nZone:\nDornogal\nKosten:\n150\n\nRunenverzierte Nullsteinrute\nWird beim Aufheben gebunden\nWerkzeug für Verzauberkunst\n+ 125 Zufallswert 1\nAnlegen: +18 Fertigkeit in Verzauberkunst von Khaz Algar\nAnlegen: Ihr braucht 1% weniger Konzentration bei Verzauberkunstformeln von Khaz Algar.\n68\n\"Dient als runenverzierte Verzauberkunstrute.\"" }
entries[445324] = { ["name"] = "Verzauberter Speerholzzauberstab", ["text"] = "Wirken in 3.5 sek. 3\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nSturmstaub (5), Kodifiziertes Grünholz\nOptionale Reagenzien:\nErmächtigen (#342) , Verzierung hinzufügen (#341) , Sekundärwerte anpassen (#365) , Verzauberungen und Ausrüstung (#378) , Authentizität des Kunsthandwerks (#354)\nBerufsausbilder:\nVerzauberkunst von Khaz Algar (40)\nKosten:\n150\n\nVerzauberter Speerholzzauberstab\nWird beim Anlegen gebunden\nDistanz Zauberstab\n270 - 451 Schattenschaden Geschwindigkeit 2.00\n(180.3 Schaden pro Sekunde)\n+1.847 Intelligenz\n+1.162 Ausdauer\n+ 222 Zufallswert 1\n+ 222 Zufallswert 2\nHaltbarkeit 90 / 90\n72" }
entries[445347] = { ["name"] = "Verzaubertes runenverziertes Heroldswappen", ["text"] = "Wirken in 3.5 sek. 2\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nAufkommendes runenverziertes Vorbotenwappen , Sturmstaub (60), Schimmernder Splitter (10), Glänzender Kristall\nBeute von:\nAbenteuer in Khaz Algar\n\nVerzaubertes runenverziertes Vorbotenwappen\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+10 Rezeptschwierigkeit\nBenutzbar mit: Rezepte aus Khaz Algar für epische Ausrüstungsteile, die mit einem Funken der Omen hergestellt werden.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"" }
entries[445354] = { ["name"] = "Verzaubertes vergoldetes Heroldswappen", ["text"] = "Wirken in 3.5 sek. 3\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nAufkommendes vergoldetes Vorbotenwappen , Sturmstaub (100), Schimmernder Splitter (15), Glänzender Kristall (2)\nBeute von:\nAbenteuer in Khaz Algar\n\nVerzaubertes vergoldetes Vorbotenwappen\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+20 Rezeptschwierigkeit\nBenutzbar mit: Rezepte aus Khaz Algar für epische Ausrüstungsteile, die mit einem Funken der Omen hergestellt werden.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"" }
entries[445355] = { ["name"] = "Szepter der strahlenden Magie", ["text"] = "Wirken in 3.5 sek. 3\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nEntweihter Zunderkasten (2), Schimmernder Splitter (6), Glänzender Kristall (2), Kodifiziertes Grünholz , Funke (#256)\nOptionale Reagenzien:\nMit Energie erfüllen (#366) , Verzierung hinzufügen (#341) , Sekundärwerte anpassen (#365) , Verzauberungen und Ausrüstung (#378) , Authentizität des Kunsthandwerks (#354) , Weiter Augmentieren (#384)\nSpezialisierung:\nEphemeren, Anreicherung und Ausrüstung - Schlachthandwerk\n\nSzepter der strahlenden Magie\nWird beim Aufheben gebunden\nDistanz Zauberstab\n907 - 1,513 Feuerschaden Geschwindigkeit 2.00\n(605.0 Schaden pro Sekunde)\n+6.201 Intelligenz\n+4.874 Ausdauer\n+ 364 Zufallswert 1\n+ 364 Zufallswert 2\nHaltbarkeit 110 / 110\n70" }
entries[445361] = { ["name"] = "Runenverzierte Bismutrute", ["text"] = "Wirken in 3.5 sek. 3\nReagenzien:\nBismutrute , Sturmstaub (10)\nOptionale Reagenzien:\nHerstellungswerte anpassen (#345) , Verzauberungen und Ausrüstung (#378) , Authentizität des Kunsthandwerks (#354)\nBerufsausbilder:\nVerzauberkunst von Khaz Algar (15)\nKosten:\n100\n\nRunenverzierte Bismutrute\nWird beim Anlegen gebunden\nWerkzeug für Verzauberkunst\n+ 80 Zufallswert 1\nAnlegen: +8 Fertigkeit in Verzauberkunst von Khaz Algar\n68\n\"Dient als runenverzierte Verzauberkunstrute.\"" }
