entries[445372] = { ["name"] = "Runenverzierte Eisenklauenrute", ["text"] = "Wirken in 3.5 sek. 2\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nHändchen fürs Kunsthandwerk (300), Barren der Schallenden Tiefen , Sturmstaub (75), Schimmernder Splitter (5)\nOptionale Reagenzien:\nHerstellungswerte anpassen (#345) , Verzauberungen und Ausrüstung (#378) , Authentizität des Kunsthandwerks (#354)\nSpezialisierung:\nEphemeren, Anreicherung und Ausrüstung - Professionelle Produktion\n\nRunenverzierte Eisenklauenrute\nWird beim Aufheben gebunden\nWerkzeug für Verzauberkunst\n+ 125 Zufallswert 1\nAnlegen: +18 Fertigkeit in Verzauberkunst von Khaz Algar\n68\n\"Dient als runenverzierte Verzauberkunstrute.\"" }
entries[445399] = { ["name"] = "Verzaubertes verwittertes Heroldswappen", ["text"] = "Wirken in 3.5 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nAufkeimendes verwittertes Vorbotenwappen , Sturmstaub (30), Schimmernder Splitter (5)\nBeute von:\nAbenteuer in Khaz Algar\n\nVerzaubertes verwittertes Vorbotenwappen\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+100 Rezeptschwierigkeit\nBenutzbar mit: Rezepte aus Khaz Algar für die meisten seltenen (blauen) Ausrüstungsteile.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"" }
