entries[445465] = { ["name"] = "Welken", ["text"] = "Gebrechen\nBelegt das Ziel mit einer abscheulichen Verwünschung, die seine Sehnen und Muskeln verbrennt und ihm sofort (19.8375% der Zaubermacht) Schattenflammenschaden sowie im Verlauf von 18 Sek. (296.544% der Zaubermacht) zusätzlichen Schattenflammenschaden zufügt.\n\nErsetzt 'Verderbnis'.\n\nZerstörung\nBelegt das Ziel mit einer abscheulichen Verwünschung, die seine Sehnen und Muskeln verbrennt und ihm sofort (19.8375% der Zaubermacht) Schattenflammenschaden sowie im Verlauf von 18 Sek. (296.544% der Zaubermacht) zusätzlichen Schattenflammenschaden zufügt.\n\nRegelmäßiger Schaden erzeugt ein Seelensplitterfragment und hat eine Chance von 50%, bei kritischen Treffern ein zusätzliches zu erzeugen.\n\nErsetzt 'Feuerbrand'." }
entries[445466] = { ["name"] = "Essenz zertrümmern", ["text"] = "Wirken in 1.5 sek.\nZerschmettert eine magische Essenz von Khaz Algar, um die Macht im Innern für Eure Verzauberkunst zu nutzen.\n\nIhr erhaltet beim Zerschmettern folgenden Effekt:\n\nZerschmetterte Essenz :\nErmächtigt von zerschmetterter magischer Essenz aus Khaz Algar. Erhöht den Einfallsreichtum, die Genialität und Mehrfachherstellung, während Ihr Zauberkunst von Khaz Algar praktiziert.\nSpezialisierung:\nSupplementäres Schmettern" }
entries[445468] = { ["name"] = "Welken", ["text"] = "1.5% von Grundmana 40 Meter Reichweite\nSofort\nGebrechen\nBelegt das Ziel mit einer abscheulichen Verwünschung, die seine Sehnen und Muskeln verbrennt und ihm sofort (19.8375% der Zaubermacht) Schattenflammenschaden sowie im Verlauf von 18 Sek. (296.544% der Zaubermacht) zusätzlichen Schattenflammenschaden zufügt.\n\nErsetzt 'Verderbnis'.\n\nZerstörung\nBelegt das Ziel mit einer abscheulichen Verwünschung, die seine Sehnen und Muskeln verbrennt und ihm sofort (19.8375% der Zaubermacht) Schattenflammenschaden sowie im Verlauf von 18 Sek. (296.544% der Zaubermacht) zusätzlichen Schattenflammenschaden zufügt.\n\nRegelmäßiger Schaden erzeugt ein Seelensplitterfragment und hat eine Chance von 50%, bei kritischen Treffern ein zusätzliches zu erzeugen.\n\nErsetzt 'Feuerbrand'." }
