entries[445475] = { ["name"] = "Surekisches Sperrfeuer", ["text"] = "Sofort\nZieht einen Bogen aus dem Arsenal, um eine Pfeilsalve nach vorne abzufeuern, die allen Gegnern innerhalb von 20 Metern ( 1 * 1478 ) Schattenschaden zufügt.\n\nBis zum Ziehen der nächsten Waffe erhaltet Ihr 6 Sek. lang eine um 6% erhöhte Geschwindigkeit, wenn Ihr Euch nach dem Stillstand bewegt. Dieser Wert erhöht sich alle 2 Sek. bis zu 5-mal um 6%." }
entries[445479] = { ["name"] = "Glutnektar", ["text"] = "Wirken in 2 sek.\nReagenzien:\nTrinkschlauch des Tiefenforschers (3), Heiße Honigwabe\nOptionale Reagenzien:\nGeheimzutat (#318)\nRezept für 10 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nCendvin\nZone:\nInsel von Dorn\nKosten:\n120\n\nGlutnektar\nBenutzen: Stellt im Verlauf von 20 Sek. ( 937500 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n68" }
entries[445480] = { ["name"] = "Energie-im-Knie", ["text"] = "Wirken in 2 sek.\nReagenzien:\nTrinkschlauch des Tiefenforschers (5)\nOptionale Reagenzien:\nGeheimzutat (#318)\nRezept für 1 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nKapitänin Oathmyt\nZone:\nHeilsturz\nKosten:\n10\n\nEnergie-im-Knie\nBenutzen: Stellt im Verlauf von 20 Sek. ( 937500 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\nEnergie-im-Knie\nWenn Ihr mindestens 10 Sek. mit Trinken verbringt, erhaltet Ihr 10 Min. lang 167 Geschwindigkeit sowie die Fähigkeit, auf dem Wasser zu laufen.\n68" }
entries[445482] = { ["name"] = "Felssturzmischgetränk", ["text"] = "Wirken in 2 sek.\nReagenzien:\nTrinkschlauch des Tiefenforschers (5), Schwammschlemmerei (3), Heiße Honigwabe , Bismut (10)\nOptionale Reagenzien:\nGeheimzutat (#318)\nRezept für 10 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nKapitänin Oathmyt\nZone:\nHeilsturz\nKosten:\n10\n\nFelssturzmischgetränk\nBenutzen: Das ist überhaupt nicht gemischt... (5 Min Abklingzeit)\n68\n\"Die perfekte Irdenenleckerei an einem heißen Tag in Khaz Algar.\"" }
entries[445483] = { ["name"] = "Klebrig-süße Leckerei", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSchwammschlemmerei (3), Heiße Honigwabe , Klumpiges Mehl (5), Kernwegstaub (5)\nOptionale Reagenzien:\nGeheimzutat (#318)\nRezept für 10 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nBeute von:\nBrutverderber Ovi'nax\nZone:\nPalast der Nerub'ar\nMuster:\nErhältlich im Auktionshaus\n\nKlebrig-süße Leckerei\nBenutzen: Werdet wieder zum Kind! (5 Min Abklingzeit)\n68\n\"Glutbienenhonig aus den oberen Höhlensystemen ist eine Delikatesse für jeden jungen Neruber.\"" }
entries[445484] = { ["name"] = "Geschmolzener Kerzenstab", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSchwammschlemmerei (3), Heiße Honigwabe , Klumpiges Mehl (5)\nOptionale Reagenzien:\nGeheimzutat (#318)\nRezept für 10 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nKapitänin Oathmyt\nZone:\nHeilsturz\nKosten:\n10\n\nGeschmolzener Kerzenstab\nBenutzen: Ein Versuch kann nicht schaden. (5 Min Abklingzeit)\n68\n\"Eine perfekte Mischung aus zäh und knusprig. Ihr könnt Euch nicht vorstellen, dies mit irgendjemandem zu teilen.\"" }
