entries[445494] = { ["name"] = "Netzbrecher", ["text"] = "Unbegrenzte Reichweite\nSofort\nRasha'nan hackt auf das Zielgebiet ein, verursacht 56987520 Naturschaden und zieht die Spielercharaktere zu sich. Diese Effekte verteilen sich gleichmäßig auf die Spielercharaktere im Umkreis von 8 Metern um den Einschlagsort.\n\nWenn 'Netzbrecher' nicht mindestens 4 Ziele trifft, erleiden alle Spielercharaktere den vollen Effekt." }
entries[445495] = { ["name"] = "Flamme verschlingen", ["text"] = "100 Meter Reichweite\nSofort\nVerheerung\n'Umhüllen' zehrt 2 Sek. von 'Feueratem' auf dem Ziel auf, lässt es explodieren und fügt allen Zielen in der Nähe 900% der aufgezehrten Menge als Schaden zu. Bei Zielen über 5 Ziele hinaus ist der Effekt verringert.\n\nBewahrung\n'Umhüllen' zehrt 2 Sek. von 'Traumatem' auf dem Ziel auf, lässt es explodieren und fügt allen Zielen in der Nähe 900% der aufgezehrten Menge als Heilung zu. Bei Zielen über 5 Ziele hinaus ist der Effekt verringert." }
entries[445497] = { ["name"] = "Schreddern", ["text"] = "20 Meter Reichweite\nWirken in 2 sek. 6 sek. Abklingzeit\nZerreißt ein gegnerisches Ziel und fügt ihm so körperlichen Schaden und zusätzlich 5 Sek. lang alle 1 Sek. körperlichen Blutungsschaden zu. Dieser Effekt ist stapelbar." }
